@import "tailwindcss";
@import "tw-animate-css";

/* Poppins + Phudu, embedded as base64 so there is nothing else to install.
   If you add more html entry points (a phone app, a DUI texture page), switch
   these to the linked variant instead — see `bunx 9am-ui fonts`. */
@import "./styles/9am-fonts.css";

/* The 9AM design language: tokens, both palettes, NUI base rules.
   Managed by 9am-ui — do not edit that file, put your own styles below. */
@import "./styles/9am-theme.css";

/* --------------------------------------------------------------------------
   Script-specific styles go here.
   -------------------------------------------------------------------------- */

import React from 'react';
import ReactDOM from 'react-dom/client';
import { VisibilityProvider } from './providers/VisibilityProvider';
import App from './components/App';
import { fetchNui } from './utils/fetchNui';
import { installSmoothScroll } from './lib/smooth-scroll';
import { initI18n } from './i18n';
import './index.css';

// Pull the locale dictionary from Lua before anything is on screen. The dev
// loader is only used by `bun run start` (plain browser, no Lua to ask) and is
// dead-code-eliminated from production builds along with the en.json chunk.
initI18n(__DEV_SEED__ ? () => import('../../locales/en.json') : undefined);

// Repairs wheel scroll in FiveM CEF and gives every scroller smooth easing.
installSmoothScroll();

// Top-level error boundary: a render crash must never leave the NUI frame
// open with focus held, so release the frame and render nothing.
class AppErrorBoundary extends React.Component<{ children: React.ReactNode }, { hasError: boolean }> {
  state = { hasError: false };

  static getDerivedStateFromError() {
    return { hasError: true };
  }

  componentDidCatch(error: unknown, errorInfo: React.ErrorInfo) {
    console.error('Unhandled UI error:', error, errorInfo);
    fetchNui('hideFrame');
  }

  render() {
    if (this.state.hasError) return null;
    return this.props.children;
  }
}

ReactDOM.createRoot(document.getElementById('root')!).render(
  <AppErrorBoundary>
    <VisibilityProvider>
      <App />
    </VisibilityProvider>
  </AppErrorBoundary>,
);

import { Button } from '@/components/ui/button';
import {
  Viewport,
  ViewportHeader,
  ViewportTitle,
  ViewportDescription,
  ViewportAction,
  ViewportContent,
} from '@/components/ui/viewport';
import { XIcon } from '@/components/ui/x';
import { ThemeToggleIcon } from '@/components/ui/theme-toggle';
import { useTheme } from '@/hooks/useTheme';
import { fetchNui } from '@/utils/fetchNui';
import { useT } from '@/i18n';

/**
 * Starting point for a 9AM script UI. Delete freely — it exists to show the
 * house style in one screen: a Viewport scroller with a pinning header, the
 * translucent control fill, and the exit affordance every 9AM NUI has.
 */
export default function App() {
  const { theme, toggleTheme } = useTheme();
  const t = useT();

  return (
    <div className="h-full w-full flex items-center justify-center p-8">
      <Viewport className="w-[900px] max-h-[80vh]" fadeColor="var(--card)">
        <ViewportHeader className="px-4">
          <ViewportTitle className="!font-[phudu] text-2xl">
            {t('ui.app.title')}
          </ViewportTitle>
          <ViewportDescription>{t('ui.app.subtitle')}</ViewportDescription>
          <ViewportAction className="flex items-center gap-2.5">
            <Button variant="default2" className="h-9 px-3" onClick={toggleTheme}>
              <ThemeToggleIcon theme={theme} size={16} />
            </Button>
            <Button variant="default2" className="h-9 px-3 gap-2.5" onClick={() => fetchNui('hideFrame')}>
              <div className="bg-foreground rounded-[4px] flex items-center justify-center w-4 h-4">
                <XIcon size={18} className="text-background" />
              </div>
              <span>{t('ui.common.close')}</span>
            </Button>
          </ViewportAction>
        </ViewportHeader>

        <ViewportContent className="px-4 pt-2">
          <div className="rounded-xl bg-black/[0.05] dark:bg-white/10 border p-6">
            <p className="text-muted-foreground text-sm">{t('ui.app.placeholder')}</p>
          </div>
        </ViewportContent>
      </Viewport>
    </div>
  );
}

import path from "path"
import tailwindcss from "@tailwindcss/vite"
import react from "@vitejs/plugin-react"
import { defineConfig } from "vite"

export default defineConfig(({ mode }) => {
  // `bun run production-build` → mode "prod": customer-ready dist with the
  // browser dev seed / mock data compiled out and console noise stripped.
  const isProd = mode === "prod"

  return {
    // Relative base: the NUI is loaded from a file path, not a web root.
    base: './',
    plugins: [react(), tailwindcss()],
    resolve: {
      alias: {
        "@": path.resolve(__dirname, "./src"),
      },
    },
    // postcss.config.js holds the oklch→CEF-safe conversion. Do not drop it.
    css: {
      postcss: './postcss.config.js'
    },
    // Compile-time flag: false in production-build, which dead-code-eliminates
    // every dev-seed/mock-data path — their chunks are never emitted to dist.
    define: {
      __DEV_SEED__: JSON.stringify(!isProd),
    },
    esbuild: isProd
      ? {
          // Strip log/info/debug/warn calls; console.error stays (support
          // diagnostics when a customer reports a UI crash).
          pure: ['console.log', 'console.info', 'console.debug', 'console.warn'],
          drop: ['debugger'],
        }
      : undefined,
    build: {
      rollupOptions: {
        // Add more HTML entry points here (a phone app, a DUI texture page…):
        //   input: { main: 'index.html', phone: 'phone.html' }
        output: {
          // Split heavyweight vendors out of the entry chunk: smaller files
          // parse faster in CEF and vendor chunks stay byte-identical between
          // releases (better caching, smaller diffs). Exact package matching —
          // substring matching pulls stray packages across groups and creates
          // circular chunks (TDZ crashes at runtime).
          manualChunks(id) {
            const m = id.replace(/\\/g, '/').match(/node_modules\/((?:@[^/]+\/)?[^/]+)/)
            if (!m) return
            const pkg = m[1]
            if (pkg === 'react' || pkg === 'react-dom' || pkg === 'scheduler') return 'vendor-react'
            if (pkg === 'recharts' || pkg.startsWith('d3-') || pkg === 'victory-vendor' || pkg === 'recharts-scale' || pkg === 'react-smooth') return 'vendor-charts'
            if (pkg === 'framer-motion' || pkg === 'motion' || pkg === 'motion-dom' || pkg === 'motion-utils') return 'vendor-motion'
            return 'vendor'
          },
        },
      },
    },
  }
})

// DO NOT REMOVE postcss-color-converter.
//
// The 9AM theme tokens are authored in oklch (registry/theme/9am-theme.css).
// FiveM's CEF is Chromium 103, which does not understand `oklch()` — without
// this step every token resolves to nothing and the whole UI renders unstyled
// in-game while looking perfectly fine in `bun run start`. This converts them
// to a CEF-safe format at build time (Tailwind v4 separately emits hex
// fallbacks ahead of each `color-mix()` behind an `@supports` guard).
//
// Verify after changing anything here:
//   bun run build && grep -c oklch dist/assets/*.css   # must be 0
export default {
    plugins: {
        'postcss-color-converter': {
            outputColorFormat: 'rgb',
            ignore: ['hex']
        },
        '@tailwindcss/postcss': {},
        autoprefixer: {}
    }
}

import js from "@eslint/js";
import globals from "globals";
import tseslint from "typescript-eslint";
import reactHooks from "eslint-plugin-react-hooks";
import reactRefresh from "eslint-plugin-react-refresh";

export default tseslint.config(
  { ignores: ["dist"] },
  {
    files: ["src/**/*.{ts,tsx}"],
    extends: [
      js.configs.recommended,
      ...tseslint.configs.recommended,
      reactHooks.configs.flat.recommended,
    ],
    languageOptions: {
      ecmaVersion: 2020,
      globals: globals.browser,
    },
    plugins: {
      "react-refresh": reactRefresh,
    },
    rules: {
      "react-refresh/only-export-components": [
        "warn",
        { allowConstantExport: true },
      ],
      // React-Compiler rules from react-hooks v7. The 9AM kit components are
      // written against these; kept as warnings so an inherited pattern in your
      // own code never blocks a build.
      "react-hooks/purity": "warn",
      "react-hooks/set-state-in-effect": "warn",
      "react-hooks/refs": "warn",
    },
  }
);
